def __init__(self, request_validator=None, token_generator=None, expires_in=None, refresh_token_generator=None):
    self.request_validator = request_validator
    self.token_generator = token_generator or random_token_generator
    self.refresh_token_generator = (
        refresh_token_generator or self.token_generator
    )
    self.expires_in = expires_in or 3600

def create_token(self, request, refresh_token=False):
    if callable(self.expires_in):
        request.expires_in = self.expires_in(request)
    else:
        request.expires_in = self.expires_in

    return self.request_validator.get_jwt_bearer_token(None, None, request)
